from flask import Flask, request, redirect, Response, render_template_string, session, url_for, abort
from functools import wraps
import sqlite3, csv, io, os, secrets, time, hmac, logging
from werkzeug.security import check_password_hash

app = Flask(__name__)

# Security configuration
_secret_key = os.environ.get("SECRET_KEY")
if not _secret_key:
    _secret_key = secrets.token_hex(32)
    logging.warning("SECRET_KEY is not set; sessions will reset when the service restarts.")
app.config.update(
    SECRET_KEY=_secret_key,
    SESSION_COOKIE_SECURE=True,       # Render serves the app over HTTPS
    SESSION_COOKIE_HTTPONLY=True,
    SESSION_COOKIE_SAMESITE="Lax",
    MAX_CONTENT_LENGTH=1 * 1024 * 1024,  # 1 MB request limit
)

DB_NAME = "academy.db"
ADMIN_PASSWORD = os.environ.get("ADMIN_PASSWORD", "")
ADMIN_PASSWORD_HASH = os.environ.get("ADMIN_PASSWORD_HASH", "")

# Simple per-process login rate limit. For multiple instances, use a shared store such as Redis.
LOGIN_WINDOW = 15 * 60
LOGIN_MAX_ATTEMPTS = 5
_login_attempts = {}

def get_db():
    conn = sqlite3.connect(DB_NAME, timeout=10)
    conn.row_factory = sqlite3.Row
    return conn

def client_key():
    return request.remote_addr or "unknown"

def login_blocked():
    now = time.time()
    key = client_key()
    attempts = [t for t in _login_attempts.get(key, []) if now - t < LOGIN_WINDOW]
    _login_attempts[key] = attempts
    return len(attempts) >= LOGIN_MAX_ATTEMPTS

def record_login_failure():
    now = time.time()
    key = client_key()
    attempts = [t for t in _login_attempts.get(key, []) if now - t < LOGIN_WINDOW]
    attempts.append(now)
    _login_attempts[key] = attempts

def clear_login_failures():
    _login_attempts.pop(client_key(), None)

def csrf_token():
    token = session.get("csrf_token")
    if not token:
        token = secrets.token_urlsafe(32)
        session["csrf_token"] = token
    return token

def validate_csrf():
    supplied = request.form.get("csrf_token", "")
    expected = session.get("csrf_token", "")
    if not supplied or not expected or not hmac.compare_digest(supplied, expected):
        abort(400, description="طلب غير صالح.")

def admin_required(view):
    @wraps(view)
    def wrapped(*args, **kwargs):
        if not session.get("is_admin"):
            return redirect(url_for("login"))
        return view(*args, **kwargs)
    return wrapped

def valid_admin_password(candidate):
    if ADMIN_PASSWORD_HASH:
        try:
            return check_password_hash(ADMIN_PASSWORD_HASH, candidate)
        except (ValueError, TypeError):
            return False
    if ADMIN_PASSWORD:
        return hmac.compare_digest(candidate, ADMIN_PASSWORD)
    return False

