@app.route("/login", methods=["GET","POST"])
def login():
    if request.method == "POST":
        validate_csrf()
        if login_blocked():
            return render_template_string(LOGIN, logo=LOGO, health_img=HEALTH_IMG,
                                          error="تم إيقاف محاولات الدخول مؤقتًا. حاول لاحقًا.",
                                          csrf_token=csrf_token()), 429
        password = request.form.get("password", "")
        if len(password) <= 256 and valid_admin_password(password):
            clear_login_failures()
            session.clear()
            session["is_admin"] = True
            session["csrf_token"] = secrets.token_urlsafe(32)
            return redirect(url_for("index"))
        record_login_failure()
        return render_template_string(LOGIN, logo=LOGO, health_img=HEALTH_IMG,
                                      error="كلمة المرور غير صحيحة.",
                                      csrf_token=csrf_token()), 401
    return render_template_string(LOGIN, logo=LOGO, health_img=HEALTH_IMG,
                                  error=None, csrf_token=csrf_token())

@app.route("/logout")
def logout():
    session.clear()
    return redirect(url_for("login"))

@app.route("/")
@admin_required
def index():
    search = request.args.get("search","").strip()[:100]
    conn = get_db()
    try:
        if search:
            members = conn.execute(
                "SELECT id,name,phone,group_name FROM members WHERE name LIKE ? OR phone LIKE ? ORDER BY id DESC",
                (f"%{search}%", f"%{search}%")
            ).fetchall()
        else:
            members = conn.execute(
                "SELECT id,name,phone,group_name FROM members ORDER BY id DESC"
            ).fetchall()
        count = conn.execute("SELECT COUNT(*) FROM members").fetchone()[0]
        groups_count = conn.execute(
            "SELECT COUNT(DISTINCT group_name) FROM members WHERE group_name IS NOT NULL AND group_name!=''"
        ).fetchone()[0]
    finally:
        conn.close()
    return render_template_string(
        HTML, logo=LOGO, banner=BANNER, health_img=HEALTH_IMG,
        edu_img=EDU_IMG, sport_img=SPORT_IMG, members=members,
        count=count, groups_count=groups_count, search=search,
        csrf_token=csrf_token()
    )

