@app.route("/add", methods=["POST"])
@admin_required
def add_member():
    validate_csrf()
    name = request.form.get("name","").strip()
    phone = request.form.get("phone","").strip()
    group_name = request.form.get("group_name","Academy").strip() or "Academy"

    if not name or not phone or len(name) > 100 or len(phone) > 30 or len(group_name) > 100:
        abort(400, description="بيانات العضو غير صالحة.")
    conn = get_db()
    try:
        conn.execute(
            "INSERT INTO members (name,phone,group_name) VALUES (?,?,?)",
            (name, phone, group_name)
        )
        conn.commit()
    except sqlite3.IntegrityError:
        pass
    finally:
        conn.close()
    return redirect(url_for("index"))

@app.route("/export")
@admin_required
def export_csv():
    conn = get_db()
    try:
        members = conn.execute(
            "SELECT name,phone,group_name FROM members ORDER BY id"
        ).fetchall()
    finally:
        conn.close()
    out = io.StringIO()
    out.write("\ufeff")
    w = csv.writer(out)
    w.writerow(["name","phone","group_name"])
    for m in members:
        w.writerow([m["name"],m["phone"],m["group_name"]])
    return Response(
        out.getvalue(),
        mimetype="text/csv",
        headers={"Content-Disposition":"attachment; filename=members.csv"}
    )

